# ---- begin inlined manzil/perception/counting.py (generated by build.py, do not edit) ----
"""Line-crossing counting and a queue (stopped-vehicle) estimate for tracked vehicles (V.4, V.5).

Pure Python, standard library only, so the same code runs in the Kaggle kernel
(`kaggle/yolo_track`, which inlines this file) and in the unit tests (`tests/test_counting.py`).

Inputs are per-frame lists of tracked boxes ``(track_id, class_id, left, top, width, height)`` in
pixels. They come either from YOLO + ByteTrack (predictions) or from the UA-DETRAC annotation XML,
whose target ids are the ground-truth track ids. Both pass through exactly the same counter, so the
counting error measures detection + tracking, not a difference in counting rules.

Counting rule (one count per track at most):
  * the reference point of a box is its centre;
  * a track is counted when the segment between two consecutive observed centres properly crosses
    the counting line segment (side changes from one strict side to the other);
  * every track is counted at most once, so a track that jitters on the line is not counted twice;
  * crossings whose intersection point lies inside a DETRAC ignored region are dropped (the
    ground truth has no labels there);
  * the class of a counted vehicle is the majority class over the whole track.

Queue estimate (a proxy, because UA-DETRAC has no stop lines or signal states): the number of
tracked vehicles in the region of interest that are *stopped*, i.e. whose centre moved less than
``stop_frac`` x (box height) over the last ``window`` frames. Dividing by the box height makes the
threshold roughly independent of the distance to the camera.
"""


import xml.etree.ElementTree as ET
from collections import Counter, defaultdict, deque
from dataclasses import dataclass, field

CLASS_NAMES = ["car", "bus", "truck", "motorcycle"]
DETRAC_MAP = {"car": 0, "van": 0, "bus": 1, "others": 2}

Point = tuple[float, float]
Box = tuple[float, float, float, float]  # left, top, width, height
Region = tuple[float, float, float, float]  # left, top, width, height


# ---------------------------------------------------------------- geometry


def centre(box: Box) -> Point:
    left, top, w, h = box
    return (left + w / 2.0, top + h / 2.0)


def side(p: Point, a: Point, b: Point) -> int:
    """+1 / -1 for the two sides of the directed line a->b, 0 if exactly on it."""
    cross = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])
    return (cross > 0) - (cross < 0)


def segment_intersection(p: Point, q: Point, a: Point, b: Point) -> Point | None:
    """Intersection of segment p-q with segment a-b, or None if they do not meet."""
    rx, ry = q[0] - p[0], q[1] - p[1]
    sx, sy = b[0] - a[0], b[1] - a[1]
    den = rx * sy - ry * sx
    if den == 0:
        return None
    t = ((a[0] - p[0]) * sy - (a[1] - p[1]) * sx) / den
    u = ((a[0] - p[0]) * ry - (a[1] - p[1]) * rx) / den
    if 0.0 <= t <= 1.0 and 0.0 <= u <= 1.0:
        return (p[0] + t * rx, p[1] + t * ry)
    return None


def in_any_region(p: Point, regions) -> bool:
    return any(x0 <= p[0] <= x0 + w and y0 <= p[1] <= y0 + h for (x0, y0, w, h) in regions)


def horizontal_line(img_w: float, img_h: float, frac: float) -> tuple[Point, Point]:
    """A full-width counting line at ``frac`` of the image height, directed left -> right.

    With image y pointing down, side() is +1 below the line and -1 above it, so a crossing from
    -1 to +1 is a vehicle moving down the image ("down")."""
    y = frac * img_h
    return (0.0, y), (float(img_w), y)


# ---------------------------------------------------------------- counting


@dataclass
class CrossingEvent:
    frame: int
    track_id: int
    direction: str  # "down"/"up" for horizontal lines: "neg_to_pos" is reported as "down"
    x: float
    y: float
    class_id: int = -1  # filled in by LineCounter.finalize() (majority vote over the track)


@dataclass
class LineCounter:
    a: Point
    b: Point
    ignored: list = field(default_factory=list)

    def __post_init__(self):
        self._last: dict[int, tuple[Point, int]] = {}  # track -> (last centre, last strict side)
        self._counted: set[int] = set()
        self._votes: dict[int, Counter] = defaultdict(Counter)
        self.events: list[CrossingEvent] = []

    def update(self, frame: int, tracks) -> list[CrossingEvent]:
        """Feed one frame of ``(track_id, class_id, left, top, w, h)``; return new crossings."""
        new = []
        for tid, cls, *box in tracks:
            tid = int(tid)
            self._votes[tid][int(cls)] += 1
            c = centre(tuple(box))
            s = side(c, self.a, self.b)
            prev = self._last.get(tid)
            if s == 0:  # exactly on the line: wait for a strict side, keep the old one
                if prev is not None:
                    self._last[tid] = (c, prev[1])
                continue
            if prev is not None and prev[1] != s and tid not in self._counted:
                hit = segment_intersection(prev[0], c, self.a, self.b)
                if hit is not None:
                    self._counted.add(tid)  # counted (or deliberately dropped) once only
                    if not in_any_region(hit, self.ignored):
                        ev = CrossingEvent(frame, tid, "down" if s > 0 else "up", hit[0], hit[1])
                        self.events.append(ev)
                        new.append(ev)
            self._last[tid] = (c, s)
        return new

    def majority_class(self, tid: int) -> int:
        votes = self._votes.get(tid)
        if not votes:
            return -1
        best = max(votes.values())
        return min(k for k, v in votes.items() if v == best)  # ties -> lowest class id

    def finalize(self) -> list[CrossingEvent]:
        for ev in self.events:
            ev.class_id = self.majority_class(ev.track_id)
        return self.events

    def running_count(self) -> int:
        return len(self.events)


def counts_by_class(events, n_classes: int = len(CLASS_NAMES)) -> list[int]:
    out = [0] * n_classes
    for ev in events:
        if 0 <= ev.class_id < n_classes:
            out[ev.class_id] += 1
    return out


# ---------------------------------------------------------------- queue estimate


@dataclass
class QueueEstimator:
    window: int = 25  # frames (1 s at UA-DETRAC's 25 fps)
    stop_frac: float = 0.25  # stopped if moved < stop_frac * box height over `window` frames
    roi: Region | None = None  # None = whole frame
    ignored: list = field(default_factory=list)
    max_gap: int = 5  # a track history is restarted after a gap of more than this many frames

    def __post_init__(self):
        self._hist: dict[int, deque] = {}

    def update(self, frame: int, tracks) -> tuple[int, set[int]]:
        """Feed one frame; return (number of stopped vehicles, their track ids)."""
        stopped = set()
        seen = set()
        for tid, _cls, *box in tracks:
            tid = int(tid)
            seen.add(tid)
            c = centre(tuple(box))
            h = self._hist.get(tid)
            if h is None or frame - h[-1][0] > self.max_gap:
                h = self._hist[tid] = deque()
            h.append((frame, c, float(box[3])))
            while h and h[0][0] < frame - self.window:
                h.popleft()
            if h[0][0] > frame - self.window:  # not observed for a full window yet
                continue
            if self.roi is not None and not in_any_region(c, [self.roi]):
                continue
            if in_any_region(c, self.ignored):
                continue
            _f0, c0, _ = h[0]
            moved = ((c[0] - c0[0]) ** 2 + (c[1] - c0[1]) ** 2) ** 0.5
            mean_h = sum(e[2] for e in h) / len(h)
            if moved < self.stop_frac * mean_h:
                stopped.add(tid)
        stale = [t for t in self._hist
                 if t not in seen and frame - self._hist[t][-1][0] > self.max_gap]
        for tid in stale:
            del self._hist[tid]
        return len(stopped), stopped


# ---------------------------------------------------------------- UA-DETRAC ground truth


def parse_detrac_tracks(text: str) -> tuple[list[Region], dict[int, list]]:
    """Parse a UA-DETRAC annotation XML into (ignored regions, {frame: [(id, cls, l, t, w, h)]}).

    The target ``id`` attribute is the ground-truth track id within the sequence."""
    root = ET.fromstring(text)
    ignored = []
    ign = root.find("ignored_region")
    if ign is not None:
        for b in ign.findall("box"):
            ignored.append(tuple(float(b.get(k)) for k in ("left", "top", "width", "height")))
    frames: dict[int, list] = {}
    for fr in root.iter("frame"):
        rows = []
        for tgt in fr.iter("target"):
            b = tgt.find("box")
            vtype = tgt.find("attribute").get("vehicle_type")
            if vtype not in DETRAC_MAP:
                raise ValueError(f"unknown DETRAC vehicle_type {vtype!r}")
            rows.append((int(tgt.get("id")), DETRAC_MAP[vtype],
                         *(float(b.get(k)) for k in ("left", "top", "width", "height"))))
        frames[int(fr.get("num"))] = rows
    return ignored, frames


# ---------------------------------------------------------------- error metrics


def count_errors(pairs) -> dict:
    """``pairs`` = [(predicted, true), ...], one per clip: MAE, bias, RMSE, relative errors."""
    pairs = list(pairs)
    n = len(pairs)
    if n == 0:
        return {"n": 0}
    err = [p - t for p, t in pairs]
    abs_err = [abs(e) for e in err]
    total_true = sum(t for _, t in pairs)
    with_true = [(p, t) for p, t in pairs if t > 0]
    return {
        "n": n,
        "mae": sum(abs_err) / n,
        "bias": sum(err) / n,
        "rmse": (sum(e * e for e in err) / n) ** 0.5,
        "max_abs_error": max(abs_err),
        "total_true": total_true,
        "total_pred": sum(p for p, _ in pairs),
        # sum |error| / sum true: the share of vehicles miscounted, weighted by clip size
        "wape": (sum(abs_err) / total_true) if total_true else None,
        # mean of per-clip |error| / true over clips with at least one true crossing
        "mape": (sum(abs(p - t) / t for p, t in with_true) / len(with_true)) if with_true else None,
        "exact_clips": sum(1 for e in err if e == 0),
    }
# ---- end inlined manzil/perception/counting.py ----

# ---- begin inlined manzil/perception/linking.py (generated by build.py, do not edit) ----
"""Link labelled boxes of sparse frames (about 2 fps) into tracks (workstream W2).

The reviewed Lahore labels exist only on frames sampled at about 2 fps and have no track ids.
To get reference line-crossing counts from them, boxes of consecutive labelled frames are linked
greedily: a box continues the nearest previous box if the centre distance, divided by the mean of
the two box diagonals, is below ``gate`` and the sizes are similar. The result goes through the
same ``LineCounter`` as the tracker output. This is an approximation (fast vehicles in dense
traffic can be linked wrongly), so counts from it are a *reference*, not exact ground truth.

Pure Python, standard library only (inlined into the Kaggle kernel `kaggle/lahore_train`).
"""



def _diag(b) -> float:
    return ((b[2] - b[0]) ** 2 + (b[3] - b[1]) ** 2) ** 0.5


def _centre(b) -> tuple[float, float]:
    return ((b[0] + b[2]) / 2.0, (b[1] + b[3]) / 2.0)


class GreedyLinker:
    """Feed frames in time order: ``update([(cls, x1, y1, x2, y2), ...])`` returns
    ``[(track_id, cls, left, top, width, height), ...]`` (the LineCounter input format)."""

    def __init__(self, gate: float = 1.5, max_size_ratio: float = 2.0, max_missed: int = 1):
        self.gate = gate
        self.max_size_ratio = max_size_ratio
        self.max_missed = max_missed  # a track survives this many frames without a match
        self._tracks: dict[int, tuple[tuple, int]] = {}  # id -> (last box, frames missed)
        self._next = 1

    def update(self, boxes) -> list[tuple]:
        boxes = [(int(c), float(x1), float(y1), float(x2), float(y2))
                 for c, x1, y1, x2, y2 in boxes]
        pairs = []
        for tid, (tb, _missed) in self._tracks.items():
            tc, td = _centre(tb), _diag(tb)
            for j, (_c, *b) in enumerate(boxes):
                bd = _diag(b)
                if td <= 0 or bd <= 0 or max(td, bd) / min(td, bd) > self.max_size_ratio:
                    continue
                bc = _centre(b)
                cost = ((tc[0] - bc[0]) ** 2 + (tc[1] - bc[1]) ** 2) ** 0.5 / ((td + bd) / 2.0)
                if cost < self.gate:
                    pairs.append((cost, tid, j))
        pairs.sort()
        used_t, used_b, assigned = set(), set(), {}
        for _cost, tid, j in pairs:
            if tid in used_t or j in used_b:
                continue
            used_t.add(tid)
            used_b.add(j)
            assigned[j] = tid
        out = []
        new_tracks: dict[int, tuple[tuple, int]] = {}
        for j, (c, *b) in enumerate(boxes):
            tid = assigned.get(j)
            if tid is None:
                tid = self._next
                self._next += 1
            new_tracks[tid] = (tuple(b), 0)
            out.append((tid, c, b[0], b[1], b[2] - b[0], b[3] - b[1]))
        for tid, (tb, missed) in self._tracks.items():
            if tid not in new_tracks and missed < self.max_missed:
                new_tracks[tid] = (tb, missed + 1)
        self._tracks = new_tracks
        return out
# ---- end inlined manzil/perception/linking.py ----

# ---- begin inlined manzil/perception/lahore_labels.py (generated by build.py, do not edit) ----
"""Six-class label tools for the Lahore footage (workstream W2).

Pure Python (standard library only), so the same code runs in Kaggle kernels and in the unit
tests (`tests/test_w2_lahore_labels.py`).

Classes (W2): ``0 car, 1 bus, 2 truck, 3 motorcycle, 4 rickshaw, 5 van``. "rickshaw" covers all
three-wheelers seen in Lahore (auto rickshaw, chingchi, loader rickshaw); "van" covers
passenger vans and Suzuki-type carry/pick-up vans. The first four ids are the same as the
four-class Manzil model (`models/yolo/manzil_yolo11s_best.pt`), so old labels stay valid.

What is here:
  * class maps from the pre-labelling detectors to the six classes;
  * IoU and a greedy cross-detector merge that turns raw detections into pre-labels;
  * reading/writing YOLO label lines (normalised centre x, centre y, width, height);
  * applying a review correction list (delete / change class / add box) to a pre-label set;
  * the split manifest (``data/lahore_video/split_manifest.csv``) loader and checks.
"""


import csv
from dataclasses import dataclass, field

CLASS_NAMES = ["car", "bus", "truck", "motorcycle", "rickshaw", "van"]
OLD_CLASS_NAMES = CLASS_NAMES[:4]  # the four-class Manzil model uses the same first ids
NEW_CLASSES = (4, 5)

# COCO-80 index -> six-class id (car 2, motorcycle 3, bus 5, truck 7)
COCO_MAP = {2: 0, 5: 1, 7: 2, 3: 3}
# the fine-tuned four-class Manzil model -> six-class id (identity)
MANZIL4_MAP = {0: 0, 1: 1, 2: 2, 3: 3}
# open-vocabulary prompts (YOLO-World) in this order -> six-class id
WORLD_PROMPTS = ["car", "bus", "truck", "motorcycle", "auto rickshaw", "loader rickshaw", "van"]
WORLD_MAP = {0: 0, 1: 1, 2: 2, 3: 3, 4: 4, 5: 4, 6: 5}

SPLITS = ("train", "val", "test")
UNUSED = "unused"  # guard-band frames next to a boundary between two splits

Box = tuple[float, float, float, float]  # x1, y1, x2, y2 in pixels


@dataclass
class Det:
    cls: int
    conf: float
    box: Box
    source: str = ""


@dataclass
class Label:
    cls: int
    box: Box
    sources: list = field(default_factory=list)
    conf: float = 1.0


# ---------------------------------------------------------------- geometry


def iou(a: Box, b: Box) -> float:
    ix = max(0.0, min(a[2], b[2]) - max(a[0], b[0]))
    iy = max(0.0, min(a[3], b[3]) - max(a[1], b[1]))
    inter = ix * iy
    if inter <= 0:
        return 0.0
    ua = (a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]) - inter
    return inter / ua if ua > 0 else 0.0


def map_dets(raw, cmap: dict[int, int], source: str) -> list[Det]:
    """``raw`` rows ``[cls, conf, x1, y1, x2, y2]`` -> Det list; classes not in cmap dropped."""
    out = []
    for c, conf, *b in raw:
        c = int(c)
        if c in cmap:
            out.append(Det(cmap[c], float(conf), tuple(float(v) for v in b), source))
    return out


# ---------------------------------------------------------------- merge


@dataclass
class MergeConfig:
    iou_thr: float = 0.5  # detections of different sources with IoU above this are one vehicle
    keep_conf: float = 0.35  # a cluster is kept if its best confidence reaches this ...
    agree_conf: float = 0.15  # ... or if >= 2 sources agree with at least this confidence
    new_class_conf: float = 0.2  # an open-vocabulary rickshaw/van this sure overrides car etc.
    min_side_px: float = 12.0  # boxes smaller than this (both sides) are ignored
    prefer_source: str = ""  # if set, a detection from this source decides the class ...
    prefer_conf: float = 0.25  # ... when it is at least this confident


def merge(dets: list[Det], cfg: MergeConfig | None = None) -> list[Label]:
    """Greedy cross-detector merge into one pre-label per vehicle.

    Detections are sorted by confidence; each seeds a cluster that absorbs every remaining
    detection with IoU >= ``iou_thr``. The box is the confidence-weighted mean of the cluster.
    Class: if ``prefer_source`` is set and that source has a detection in the cluster with
    confidence >= ``prefer_conf``, its class wins. Otherwise, if the cluster holds a rickshaw/van
    (from the open-vocabulary detector) with confidence >= ``new_class_conf``, the more
    confident of the two wins; otherwise the class
    with the largest summed confidence. These are *pre-labels*; review decides the final label.
    """
    cfg = cfg or MergeConfig()
    pool = sorted((d for d in dets if max(d.box[2] - d.box[0], d.box[3] - d.box[1])
                   >= cfg.min_side_px), key=lambda d: -d.conf)
    used = [False] * len(pool)
    labels = []
    for i, seed in enumerate(pool):
        if used[i]:
            continue
        used[i] = True
        cluster = [seed]
        for j in range(i + 1, len(pool)):
            if not used[j] and iou(seed.box, pool[j].box) >= cfg.iou_thr:
                used[j] = True
                cluster.append(pool[j])
        best = max(d.conf for d in cluster)
        sources = sorted({d.source for d in cluster})
        agreeing = {d.source for d in cluster if d.conf >= cfg.agree_conf}
        if best < cfg.keep_conf and len(agreeing) < 2:
            continue
        new = [d for d in cluster if d.cls in NEW_CLASSES and d.conf >= cfg.new_class_conf]
        pref = [d for d in cluster if cfg.prefer_source and d.source == cfg.prefer_source
                and d.conf >= cfg.prefer_conf]
        if pref:
            cls = max(pref, key=lambda d: d.conf).cls
        elif new:
            cls = max(new, key=lambda d: d.conf).cls
        else:
            score: dict[int, float] = {}
            for d in cluster:
                score[d.cls] = score.get(d.cls, 0.0) + d.conf
            cls = min(score, key=lambda c: (-score[c], c))
        wsum = sum(d.conf for d in cluster)
        box = tuple(sum(d.box[k] * d.conf for d in cluster) / wsum for k in range(4))
        labels.append(Label(cls, box, sources, round(best, 4)))
    return labels


# ---------------------------------------------------------------- YOLO label format


def to_yolo_line(lab: Label, w: float, h: float) -> str:
    x1, y1, x2, y2 = (max(0.0, min(v, lim)) for v, lim in zip(lab.box, (w, h, w, h), strict=True))
    return (f"{lab.cls} {(x1 + x2) / 2 / w:.6f} {(y1 + y2) / 2 / h:.6f} "
            f"{(x2 - x1) / w:.6f} {(y2 - y1) / h:.6f}")


def from_yolo_line(line: str, w: float, h: float) -> Label:
    c, cx, cy, bw, bh = line.split()
    cx, cy, bw, bh = float(cx) * w, float(cy) * h, float(bw) * w, float(bh) * h
    return Label(int(c), (cx - bw / 2, cy - bh / 2, cx + bw / 2, cy + bh / 2))


# ---------------------------------------------------------------- review corrections


def apply_review(labels: list[Label], ops: list[dict]) -> tuple[list[Label], dict]:
    """Apply review operations for one image to its pre-labels (indexed as rendered, 0-based).

    ops: ``{"op": "del", "id": i}``, ``{"op": "cls", "id": i, "to": c}``,
    ``{"op": "add", "cls": c, "box": [x1, y1, x2, y2]}``.
    Returns the corrected labels and a change log ``{"deleted": n, "reclassed": n, "added": n,
    "by_class": {name: {"deleted", "reclassed_to", "reclassed_from", "added"}}}``.
    """
    out = [Label(lab.cls, lab.box, list(lab.sources), lab.conf) for lab in labels]
    dead = set()
    log = {"deleted": 0, "reclassed": 0, "added": 0,
           "by_class": {n: {"deleted": 0, "reclassed_from": 0, "reclassed_to": 0, "added": 0}
                        for n in CLASS_NAMES}}
    added = []
    for op in ops:
        kind = op["op"]
        if kind in ("del", "cls"):
            i = int(op["id"])
            if not 0 <= i < len(out) or i in dead:
                raise ValueError(f"bad box id {i} in {op}")
            if kind == "del":
                dead.add(i)
                log["deleted"] += 1
                log["by_class"][CLASS_NAMES[out[i].cls]]["deleted"] += 1
            else:
                to = int(op["to"])
                if to == out[i].cls:
                    continue
                log["reclassed"] += 1
                log["by_class"][CLASS_NAMES[out[i].cls]]["reclassed_from"] += 1
                log["by_class"][CLASS_NAMES[to]]["reclassed_to"] += 1
                out[i].cls = to
                out[i].sources.append("review")
        elif kind == "add":
            c = int(op["cls"])
            x1, y1, x2, y2 = (float(v) for v in op["box"])
            if not (x2 > x1 and y2 > y1) or c not in range(len(CLASS_NAMES)):
                raise ValueError(f"bad add {op}")
            added.append(Label(c, (x1, y1, x2, y2), ["review"], 1.0))
            log["added"] += 1
            log["by_class"][CLASS_NAMES[c]]["added"] += 1
        else:
            raise ValueError(f"unknown op {op}")
    return [lab for i, lab in enumerate(out) if i not in dead] + added, log


# ---------------------------------------------------------------- split manifest


def load_manifest(path) -> list[dict]:
    """Read the split manifest CSV and check it: known splits, unique images, and no shot in
    more than one split (the split is by shot, never by frame)."""
    with open(path, newline="") as f:
        rows = list(csv.DictReader(f))
    check_manifest(rows)
    return rows


def check_manifest(rows: list[dict]) -> None:
    seen = set()
    shot_split: dict[tuple[str, str], str] = {}
    for r in rows:
        if r["split"] not in (*SPLITS, UNUSED):
            raise ValueError(f"unknown split {r['split']!r} for {r['image']}")
        if r["image"] in seen:
            raise ValueError(f"duplicate image {r['image']}")
        seen.add(r["image"])
        if r["split"] == UNUSED:
            continue
        key = (r["video"], str(r["shot"]))
        if shot_split.setdefault(key, r["split"]) != r["split"]:
            raise ValueError(f"shot {key} appears in more than one split")


def split_by_shot(frames: list[dict], test_shots: set, val_shots: set,
                  boundaries: dict | None = None, guard_s: float = 0.0) -> list[dict]:
    """Assign every frame row (``video``, ``shot``, ``image``, ``time_s``...) to a split by its
    shot key ``(video, shot)``; shots in neither set are train.

    ``boundaries`` maps ``(video, shot)`` to ``(start_s, end_s)``. A frame within ``guard_s``
    seconds of a boundary shared with the neighbouring shot (shot +- 1) of a *different* split is
    marked ``unused``, so the same vehicles never appear in two splits."""

    def split_of(key):
        return "test" if key in test_shots else "val" if key in val_shots else "train"

    out = []
    for r in frames:
        key = (r["video"], int(r["shot"]))
        split = split_of(key)
        if boundaries and guard_s > 0:
            t = float(r["time_s"])
            start, end = boundaries[key]
            prev_key, next_key = (key[0], key[1] - 1), (key[0], key[1] + 1)
            if (prev_key in boundaries and split_of(prev_key) != split and t - start < guard_s) \
                    or (next_key in boundaries and split_of(next_key) != split
                        and end - t < guard_s):
                split = UNUSED
        out.append({**r, "split": split})
    check_manifest(out)
    return out
# ---- end inlined manzil/perception/lahore_labels.py ----


NAMES = CLASS_NAMES  # six classes (lahore_labels)


def sh(cmd):
    print("+", cmd, flush=True)
    subprocess.run(cmd, shell=True, check=True)


def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def one(pattern):
    hits = sorted(glob.glob(pattern, recursive=True))
    if not hits:
        raise FileNotFoundError(pattern)
    return hits[0]


def write_yaml(path, root, test_dir, names):
    with open(path, "w") as f:
        f.write(f"path: {root}\ntrain: images/train\nval: images/val\ntest: images/{test_dir}\n"
                f"names: {dict(enumerate(names))}\n")


def read_labels(path):
    rows = []
    with open(path) as f:
        for ln in f:
            p = ln.split()
            if p:
                rows.append((int(p[0]), *map(float, p[1:])))
    return rows


def summarise(m):
    box = m.box
    per = {}
    for i, c in enumerate(box.ap_class_index):
        per[m.names[int(c)]] = {"precision": float(box.p[i]), "recall": float(box.r[i]),
                                "mAP50": float(box.ap50[i]), "mAP50_95": float(box.ap[i])}
    n = max(1, len(per))
    return {"classes_evaluated": list(per),
            "precision": sum(v["precision"] for v in per.values()) / n,
            "recall": sum(v["recall"] for v in per.values()) / n,
            "mAP50": sum(v["mAP50"] for v in per.values()) / n,
            "mAP50_95": sum(v["mAP50_95"] for v in per.values()) / n,
            "per_class": per}


def confusion(model, img_dir, lab_dir, n_model_classes):
    """Rows = true class (6 + background), columns = predicted class (+ missed)."""
    from PIL import Image

    k = len(NAMES)
    mat = [[0] * (k + 1) for _ in range(k + 1)]
    for p in sorted(glob.glob(f"{img_dir}/*.jpg")):
        w, h = Image.open(p).size
        gts = [from_yolo_line(" ".join(map(str, r)), w, h)
               for r in read_labels(f"{lab_dir}/{os.path.basename(p)[:-4]}.txt")]
        r = model.predict(p, imgsz=IMGSZ, conf=CM_CONF, iou=0.6, device=0, max_det=500,
                          verbose=False)[0]
        preds = sorted(zip(r.boxes.conf.tolist(), r.boxes.cls.int().tolist(),
                           r.boxes.xyxy.tolist(), strict=True), reverse=True)
        used = set()
        for _conf, pc, pb in preds:
            best, bj = CM_IOU, None
            for j, g in enumerate(gts):
                if j in used:
                    continue
                v = iou(tuple(pb), g.box)
                if v >= best:
                    best, bj = v, j
            if bj is None:
                mat[k][pc] += 1  # false positive (background predicted as pc)
            else:
                used.add(bj)
                mat[gts[bj].cls][pc] += 1
        for j, g in enumerate(gts):
            if j not in used:
                mat[g.cls][k] += 1  # missed
    return {"rows_true": [*NAMES, "background"], "cols_pred": [*NAMES, "missed"],
            "matrix": mat, "conf": CM_CONF, "iou": CM_IOU, "model_classes": n_model_classes}


def main():
    t_start = time.time()
    sh(f"pip install -q {ULTRALYTICS}")
    import cv2
    import torch
    import ultralytics
    from ultralytics import YOLO

    os.makedirs(OUT, exist_ok=True)
    base = one(f"{INPUT}/**/out/best.pt")
    assert sha256(base) == WEIGHTS_SHA256, "base weights checksum"
    frames_dir = os.path.dirname(one(f"{INPUT}/**/frames/v1_s0_*.jpg"))
    shots = json.load(open(one(f"{INPUT}/**/shots.json")))["videos"]
    lab_root = os.path.dirname(one(f"{INPUT}/**/split_manifest.csv"))
    manifest = list(csv.DictReader(open(f"{lab_root}/split_manifest.csv")))
    check_manifest(manifest)
    far = json.load(open(f"{lab_root}/far_field.json"))
    old_root = os.path.dirname(one(f"{INPUT}/**/manzil_yolo/data.yaml"))

    # labels checksum (sorted file names + contents) for the record
    hsh = hashlib.sha256()
    for p in sorted(glob.glob(f"{lab_root}/labels/*.txt")):
        hsh.update(os.path.basename(p).encode())
        hsh.update(open(p, "rb").read())
    labels_sha = hsh.hexdigest()

    # ---- 1. dataset
    D = f"{W}/lahore"
    splits = {"train": [], "val": [], "test_v1": [], "test_v2": []}
    for r in manifest:
        if r["split"] == "unused":
            continue
        key = r["split"] if r["split"] != "test" else f"test_{r['video']}"
        stem = r["image"][:-4]
        if not os.path.exists(f"{lab_root}/labels/{stem}.txt"):
            raise FileNotFoundError(f"no reviewed label file for {r['image']} ({r['split']})")
        splits[key].append(r)
    for d in ("train", "val", "test_v1", "test_v2", "test"):
        for kind in ("images", "labels"):
            os.makedirs(f"{D}/{kind}/{d}", exist_ok=True)
    box_counts = {}
    for key, rows in splits.items():
        cnt = [0] * len(NAMES)
        for r in rows:
            stem = r["image"][:-4]
            img = cv2.imread(f"{frames_dir}/{r['image']}")
            img[:int(round(far[r["image"]]))] = GREY
            lab = open(f"{lab_root}/labels/{stem}.txt").read()
            for row in read_labels(f"{lab_root}/labels/{stem}.txt"):
                cnt[row[0]] += 1
            targets = [(key, stem)]
            if key == "train":
                targets += [(key, f"{stem}_rep{i}") for i in range(1, REPEAT)]
            if key.startswith("test_"):
                targets.append(("test", stem))
            for d, name in targets:
                cv2.imwrite(f"{D}/images/{d}/{name}.jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 95])
                with open(f"{D}/labels/{d}/{name}.txt", "w") as f:
                    f.write(lab)
        box_counts[key] = {"images": len(rows), "boxes": dict(zip(NAMES, cnt, strict=True))}
    rng = random.Random(SEED)
    old_train = sorted(os.listdir(f"{old_root}/images/train"))
    replay = (rng.sample([f for f in old_train if f.startswith("detrac_")], REPLAY_DETRAC)
              + rng.sample([f for f in old_train if f.startswith("coco_")], REPLAY_COCO))
    for f in replay:
        os.symlink(f"{old_root}/images/train/{f}", f"{D}/images/train/{f}")
        shutil.copy(f"{old_root}/labels/train/{f[:-4]}.txt", f"{D}/labels/train/{f[:-4]}.txt")
    print(json.dumps(box_counts, indent=1), flush=True)
    yamls = {}
    for t in ("test", "test_v1", "test_v2"):
        yamls[t] = f"{W}/lahore_{t}.yaml"
        write_yaml(yamls[t], D, t, NAMES)
    # label variants for the old four-class model
    for variant in ("old4", "oldconv"):
        for t in ("test", "test_v1", "test_v2"):
            # hard links, not a symlinked folder: Ultralytics resolves symlinks and would then
            # read the six-class labels next to the original images (the version-1 crash)
            os.makedirs(f"{W}/{variant}/images/{t}", exist_ok=True)
            os.makedirs(f"{W}/{variant}/labels/{t}", exist_ok=True)
            for img in glob.glob(f"{D}/images/{t}/*.jpg"):
                dst = f"{W}/{variant}/images/{t}/{os.path.basename(img)}"
                if not os.path.exists(dst):
                    os.link(img, dst)
            for p in glob.glob(f"{D}/labels/{t}/*.txt"):
                rows = []
                for c, *xywh in read_labels(p):
                    if c == 5 and variant == "oldconv":
                        c = 0
                    if c < 4:
                        rows.append(" ".join([str(c), *(f"{v:.6f}" for v in xywh)]))
                with open(f"{W}/{variant}/labels/{t}/{os.path.basename(p)}", "w") as f:
                    f.write("\n".join(rows) + ("\n" if rows else ""))
            y = f"{W}/{variant}_{t}.yaml"
            with open(y, "w") as f:
                f.write(f"path: {W}/{variant}\ntrain: images/{t}\nval: images/{t}\n"
                        f"test: images/{t}\nnames: {dict(enumerate(OLD_CLASS_NAMES))}\n")
            yamls[f"{variant}_{t}"] = y

    gpus = torch.cuda.device_count()
    results = {"versions": {"ultralytics": ultralytics.__version__, "torch": torch.__version__,
                            "python": sys.version.split()[0]},
               "config": {"imgsz": IMGSZ, "epochs": EPOCHS, "patience": PATIENCE,
                          "batch": BATCH_PER_GPU * max(1, gpus), "seed": SEED, "gpus": gpus,
                          "repeat_lahore_train": REPEAT, "replay_detrac": REPLAY_DETRAC,
                          "replay_coco": REPLAY_COCO, "base_weights_sha256": WEIGHTS_SHA256},
               "labels_sha256": labels_sha, "dataset": box_counts,
               "label_status": "model-assisted, Claude-reviewed; test split preliminary "
                               "(not yet checked by a team member)"}

    def evaluate(model, yaml_path, name, imgsz=IMGSZ):
        m = model.val(data=yaml_path, split="test", imgsz=imgsz, batch=8, device=0,
                      project=f"{W}/runs", name=name, plots=True, verbose=False, exist_ok=True)
        s = summarise(m)
        print(name, json.dumps(s), flush=True)
        return s

    # ---- 2. train (skipped when the version-1 weights are attached)
    pre6 = sorted(glob.glob(f"{INPUT}/**/{WEIGHTS6_NAME}", recursive=True))
    if pre6:
        if sha256(pre6[0]) != WEIGHTS6_SHA256:
            raise RuntimeError("six-class weights checksum")
        new_path = pre6[0]
        run = os.path.dirname(new_path)  # results.csv and args.yaml of the training run sit beside
        results["training"] = "kernel manzil-lahore-train version 1 (16 Nov 2026); reused here"
    else:
        t0 = time.time()
        model = YOLO(base)
        model.train(data=yamls["test"], epochs=EPOCHS, imgsz=IMGSZ,
                    batch=BATCH_PER_GPU * max(1, gpus), seed=SEED, deterministic=True,
                    patience=PATIENCE, workers=4, device=list(range(gpus)) if gpus > 1 else 0,
                    project=f"{W}/runs", name="lahore6", exist_ok=True, plots=True)
        results["train_seconds"] = round(time.time() - t0, 1)
        run = f"{W}/runs/lahore6"
        new_path = f"{OUT}/{WEIGHTS6_NAME}"
        shutil.copy(f"{run}/weights/best.pt", new_path)
    results["weights_sha256"] = sha256(new_path)
    with open(f"{run}/results.csv") as f:
        rows = list(csv.DictReader(f))
    key = next(k for k in rows[0] if "mAP50-95" in k)
    best_row = max(rows, key=lambda r: float(r[key]))
    results["best_epoch"] = int(float(best_row[next(k for k in best_row if "epoch" in k)]))
    results["epochs_run"] = len(rows)

    # ---- 3. Lahore test
    new = YOLO(new_path)
    old = YOLO(base)
    results["lahore_test"] = {"new_six_class": {}, "old_model_old4": {}, "old_model_oldconv": {},
                              "confusion": {}}
    for t in ("test", "test_v1", "test_v2"):
        results["lahore_test"]["new_six_class"][t] = evaluate(new, yamls[t], f"new_{t}")
        results["lahore_test"]["old_model_old4"][t] = evaluate(old, yamls[f"old4_{t}"],
                                                               f"old4_{t}")
        results["lahore_test"]["old_model_oldconv"][t] = evaluate(old, yamls[f"oldconv_{t}"],
                                                                  f"oldconv_{t}")
        results["lahore_test"]["confusion"][t] = {
            "new": confusion(new, f"{D}/images/{t}", f"{D}/labels/{t}", 6),
            "old": confusion(old, f"{D}/images/{t}", f"{D}/labels/{t}", 4)}
    results["lahore_val_new"] = summarise(new.val(
        data=yamls["test"], split="val", imgsz=IMGSZ, batch=8, device=0, project=f"{W}/runs",
        name="new_val", plots=False, verbose=False, exist_ok=True))

    # ---- 4. forgetting check on the old test sets (imgsz 640, as in results/vision)
    results["old_test_sets_new_model"] = {}
    for t in ("test", "test_motorcycle"):
        y = f"{W}/oldset_{t}.yaml"
        write_yaml(y, old_root, t, NAMES)
        results["old_test_sets_new_model"][t] = evaluate(new, y, f"new_oldset_{t}", imgsz=640)

    # ---- 5. line counting on the test shots
    by_shot = {}
    for r in manifest:
        if r["split"] == "test":
            by_shot.setdefault((r["video"], int(r["shot"])), []).append(r)
    count_rows, event_rows = [], []
    for (vid, shot), rows in sorted(by_shot.items()):
        rows.sort(key=lambda r: int(r["frame"]))
        wd, ht = int(rows[0]["width"]), int(rows[0]["height"])
        far_y = max(far[r["image"]] for r in rows)
        y_line = far_y + LINE_FRAC * (ht - far_y)
        line = ((0.0, y_line), (float(wd), y_line))
        f0, f1 = int(rows[0]["frame"]), int(rows[-1]["frame"])
        fps = shots[vid]["fps"]
        info = {"video": vid, "shot": shot, "first_frame": f0, "last_frame": f1,
                "seconds": round((f1 - f0) / fps, 2), "labelled_frames": len(rows),
                "far_row": far_y, "line_y": round(y_line, 1)}

        def keep(tracks, far_y=far_y):
            return [t for t in tracks if t[3] + t[5] / 2.0 >= far_y]

        def record(method, model_name, events, info=info):
            pc = counts_by_class(events, len(NAMES))
            row = {**info, "method": method, "model": model_name, "total": len(events),
                   "down": sum(1 for e in events if e.direction == "down"),
                   "up": sum(1 for e in events if e.direction == "up")}
            for c, n in enumerate(NAMES):
                row[n] = pc[c]
            count_rows.append(row)
            for e in events:
                event_rows.append({"video": info["video"], "shot": info["shot"], "method": method,
                                   "model": model_name, "frame": e.frame, "track_id": e.track_id,
                                   "class": NAMES[e.class_id], "direction": e.direction,
                                   "x": round(e.x, 1), "y": round(e.y, 1)})
            print(row, flush=True)

        # reference: reviewed labels linked at ~2 fps
        linker, counter = GreedyLinker(), LineCounter(*line)
        for r in rows:
            labs = [from_yolo_line(" ".join(map(str, x)), wd, ht)
                    for x in read_labels(f"{lab_root}/labels/{r['image'][:-4]}.txt")]
            counter.update(int(r["frame"]), keep(linker.update([(g.cls, *g.box) for g in labs])))
        record("labels_linked_2fps", "reviewed labels", counter.finalize())

        for mname, mpath in (("new6", new_path), ("old4", base)):
            # detections on the labelled frames, linked the same way as the reference
            m = YOLO(mpath)
            linker, counter = GreedyLinker(), LineCounter(*line)
            for r in rows:
                res = m.predict(f"{D}/images/test/{r['image']}", imgsz=IMGSZ, conf=CM_CONF,
                                iou=0.6, device=0, max_det=500, verbose=False)[0]
                boxes = [(c, *b) for c, b in zip(res.boxes.cls.int().tolist(),
                                                 res.boxes.xyxy.tolist(), strict=True)]
                counter.update(int(r["frame"]), keep(linker.update(boxes)))
            record("detections_linked_2fps", mname, counter.finalize())

            # every video frame + ByteTrack
            m = YOLO(mpath)
            counter = LineCounter(*line)
            cap = cv2.VideoCapture(one(f"{INPUT}/**/{VIDEOS[vid]}"))
            cap.set(cv2.CAP_PROP_POS_FRAMES, 0)
            i = 0
            samples = {f0 + (f1 - f0) // 3, f0 + 2 * (f1 - f0) // 3}
            while True:
                ok, fr = cap.read()
                if not ok or i > f1:
                    break
                if i >= f0:
                    if fr.shape[1] != wd:
                        fr = cv2.resize(fr, (wd, ht), interpolation=cv2.INTER_AREA)
                    fr[:int(round(far_y))] = GREY
                    res = m.track(fr, persist=True, tracker=TRACKER, imgsz=IMGSZ, device=0,
                                  verbose=False)[0]
                    tracks = []
                    if res.boxes is not None and res.boxes.id is not None:
                        for (x1, y1, x2, y2), tid, c in zip(res.boxes.xyxy.tolist(),
                                                            res.boxes.id.int().tolist(),
                                                            res.boxes.cls.int().tolist(),
                                                            strict=True):
                            tracks.append((tid, c, x1, y1, x2 - x1, y2 - y1))
                    tracks = keep(tracks)
                    counter.update(i, tracks)
                    if mname == "new6" and i in samples:
                        cv2.line(fr, (0, int(y_line)), (wd, int(y_line)), (0, 255, 255), 2)
                        for tid, c, x, y, bw, bh in tracks:
                            cv2.rectangle(fr, (int(x), int(y)), (int(x + bw), int(y + bh)),
                                          (60, 220, 60), 2)
                            cv2.putText(fr, f"{tid} {NAMES[c]}", (int(x), max(12, int(y) - 4)),
                                        cv2.FONT_HERSHEY_SIMPLEX, 0.45, (255, 255, 255), 1,
                                        cv2.LINE_AA)
                        cv2.putText(fr, f"count {counter.running_count()}", (8, int(far_y) + 28),
                                    cv2.FONT_HERSHEY_SIMPLEX, 0.8, (0, 255, 255), 2, cv2.LINE_AA)
                        small = cv2.resize(fr, (960, int(960 * ht / wd)),
                                           interpolation=cv2.INTER_AREA)
                        cv2.imwrite(f"{OUT}/sample_{vid}_s{shot}_f{i:05d}.jpg", small,
                                    [cv2.IMWRITE_JPEG_QUALITY, 80])
                i += 1
            cap.release()
            record("bytetrack_all_frames", mname, counter.finalize())

    def write_csv(name, data):
        with open(f"{OUT}/{name}", "w", newline="") as f:
            wr = csv.DictWriter(f, fieldnames=list(data[0].keys()))
            wr.writeheader()
            wr.writerows(data)

    write_csv("counts.csv", count_rows)
    if event_rows:
        write_csv("events.csv", event_rows)

    for f in ["results.csv", "results.png", "args.yaml", "labels.jpg"]:
        if os.path.exists(f"{run}/{f}"):
            shutil.copy(f"{run}/{f}", OUT)
    for name in ("new_test", "new_test_v1", "new_test_v2", "old4_test", "oldconv_test"):
        for f in ("confusion_matrix.png", "confusion_matrix_normalized.png", "BoxPR_curve.png"):
            p = f"{W}/runs/{name}/{f}"
            if os.path.exists(p):
                shutil.copy(p, f"{OUT}/{name}_{f}")
    results["seconds_total"] = round(time.time() - t_start, 1)
    results["device"] = torch.cuda.get_device_name(0)
    json.dump(results, open(f"{OUT}/metrics.json", "w"), indent=2)
    for d in ("lahore", "old4", "oldconv", "runs"):
        shutil.rmtree(f"{W}/{d}", ignore_errors=True)
    print("done", results["seconds_total"], "s")


if __name__ == "__main__":
    main()
